<template><div class="page-heading"><div><div class="eyebrow">PLATFORM CONFIGURATION</div><h1>系统设置</h1><p>账号安全、系统配置、用户权限与审计记录</p></div></div>
  <div class="settings-grid">
    <section class="surface settings-panel">
      <div class="surface-head"><div><h3>数据与生命周期</h3><p>历史消息、日志与运行数据归档</p></div></div>
      <el-form label-position="top">
        <el-form-item label="数据保留周期（天）" extra="超过该天数的消息、系统日志和任务记录将被自动清理；设为 0 表示永久保留。">
          <div style="display:flex;gap:12px;width:100%">
            <el-input-number v-model="retentionDays" :min="0" :max="365" style="width:180px"/>
            <el-button type="primary" :loading="savingRetention" @click="saveRetention">保存设置</el-button>
          </div>
        </el-form-item>
      </el-form>
      <el-alert class="security-note" title="每日 03:20 自动执行一次数据清理（可在「定时任务」停用或改时间），保留天数由上方设置控制；填 0 表示永久保留。" type="info" :closable="false" show-icon/>
    </section>
    <section class="surface settings-panel">
      <div class="surface-head"><div><h3>告警通知</h3><p>系统严重错误第三方推送</p></div></div>
      <el-form label-position="top">
        <el-form-item label="通道类型">
          <el-select v-model="alertChannelType" style="width:100%">
            <el-option label="自动检测 (根据 Webhook URL)" value="auto"/>
            <el-option label="飞书 (Feishu/Lark)" value="feishu"/>
            <el-option label="钉钉 (DingTalk)" value="dingtalk"/>
            <el-option label="企业微信 (WeCom)" value="wechat"/>
            <el-option label="通用 Webhook (JSON)" value="custom"/>
          </el-select>
        </el-form-item>
        <el-form-item label="Webhook URL" extra="支持飞书/钉钉/企业微信群机器人 Webhook 地址">
          <el-input v-model="alertWebhookUrl" placeholder="https://open.feishu.cn/open-apis/bot/v2/hook/..."/>
        </el-form-item>
        <div style="display:flex;gap:10px">
          <el-button type="primary" :loading="savingAlert" @click="saveAlertConfig">保存配置</el-button>
          <el-button :loading="testingAlert" @click="testAlertWebhook">测试推送</el-button>
        </div>
      </el-form>
      <el-alert class="security-note" title="机器人离线、关键接口异常时推送到上述 Webhook；同类告警 3 分钟内只发一次，避免刷屏。" type="info" :closable="false" show-icon/>
    </section>
    <UpdatePanel />
    <section class="surface settings-panel"><div class="surface-head"><div><h3>安全设置</h3><p>保护管理后台凭据</p></div></div><el-form ref="passwordRef" :model="password" :rules="passwordRules" label-position="top"><el-form-item label="当前密码" prop="old_password"><el-input v-model="password.old_password" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码" prop="new_password"><el-input v-model="password.new_password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认新密码" prop="confirm"><el-input v-model="password.confirm" type="password" show-password autocomplete="new-password"/></el-form-item><el-button type="primary" :loading="passwordLoading" @click="changePassword">修改密码</el-button></el-form><el-alert class="security-note" title="AppSecret、API Key 等敏感配置仅加密存储，查询接口不会返回完整密钥。" type="info" :closable="false" show-icon/></section>
  <section class="surface settings-panel security-panel"><div class="surface-head"><div><h3>两步验证</h3><p>使用身份验证器保护管理后台登录</p></div><el-tag :type="totpEnabled ? 'success' : 'info'" effect="dark">{{ totpEnabled ? '已启用' : '未启用' }}</el-tag></div><div v-if="!totpEnabled && !totpSetup" class="security-action"><span>启用后，登录时需要输入身份验证器生成的 6 位验证码。</span><el-button type="primary" @click="setupTotp">开始绑定</el-button></div><div v-if="totpSetup" class="totp-setup"><div class="totp-qr"><img v-if="totpQr" :src="totpQr" alt="TOTP 绑定二维码" /><span v-else>二维码生成中…</span></div><div class="totp-copy"><el-alert title="请使用 Google Authenticator、Microsoft Authenticator 或 1Password 扫描二维码" type="info" :closable="false" show-icon /><el-form label-position="top" @submit.prevent="confirmTotp"><el-form-item label="手动密钥"><el-input :model-value="totpSetup.secret" readonly><template #append><el-button @click="copyText(totpSetup.secret)">复制</el-button></template></el-input></el-form-item><el-form-item label="验证码"><el-input v-model="totpCode" maxlength="6" inputmode="numeric" placeholder="输入身份验证器中的 6 位验证码" /></el-form-item><div><el-button @click="cancelTotpSetup">取消</el-button><el-button type="primary" :loading="totpLoading" @click="confirmTotp">确认并启用</el-button></div></el-form></div></div><div v-if="totpEnabled" class="security-action"><span>已启用动态验证码。关闭前需要验证当前密码和验证码。</span><el-button type="danger" plain @click="disableTotpDialog=true">关闭两步验证</el-button></div></section>
  <section class="surface settings-panel sessions-panel"><div class="surface-head"><div><h3>活跃会话</h3><p>查看当前登录设备，发现异常时可立即撤销</p></div><el-button :loading="sessionsLoading" @click="loadSessions()">刷新</el-button></div><el-table :data="sessions" stripe empty-text="暂无其它活跃会话"><el-table-column label="设备 / 浏览器" min-width="250"><template #default="s"><b>{{s.row.user_agent || '未知设备'}}</b><div class="subtext">{{s.row.ip || '未知 IP'}} · 最近使用 {{formatDate(s.row.last_seen_at)}}</div></template></el-table-column><el-table-column prop="created_at" label="登录时间" width="165"><template #default="s">{{formatDate(s.row.created_at)}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.current ? 'success' : 'info'" size="small">{{s.row.current ? '当前会话' : '活跃'}}</el-tag></template></el-table-column><el-table-column label="操作" width="100"><template #default="s"><el-button v-if="!s.row.current" link type="danger" @click="revokeSession(s.row)">撤销</el-button></template></el-table-column></el-table><div class="session-footer"><span>撤销其它会话会保留当前设备</span><el-button text type="warning" @click="revokeOtherSessions">撤销其它会话</el-button></div></section>
  <section class="surface settings-panel users-panel"><div class="surface-head"><div><h3>后台用户</h3><p>RBAC 角色与访问权限</p></div><el-button type="primary" :icon="Plus" @click="userDialog=true">添加用户</el-button></div><el-table :data="users" v-loading="userLoading" stripe><el-table-column prop="username" label="用户名" min-width="120"/><el-table-column prop="display_name" label="显示名称" min-width="120"/><el-table-column label="角色" width="115"><template #default="s">{{s.row.role?.name||'—'}}</template></el-table-column><el-table-column prop="is_active" label="状态" width="85"><template #default="s"><el-tag :type="s.row.is_active?'success':'info'" effect="dark">{{s.row.is_active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="last_login_at" label="最近登录" width="165"><template #default="s">{{formatDate(s.row.last_login_at)}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="s"><el-button link type="primary" @click="toggleUser(s.row)">{{s.row.is_active?'停用':'启用'}}</el-button></template></el-table-column></el-table></section>
  <section class="surface settings-panel audit-panel"><div class="surface-head"><div><h3>操作审计</h3><p>记录后台用户的关键操作</p></div><el-button text :icon="Refresh" @click="loadAudit()">刷新</el-button></div><el-table :data="audits" v-loading="auditLoading" stripe><el-table-column prop="created_at" label="时间" width="165"><template #default="s">{{formatDate(s.row.created_at)}}</template></el-table-column><el-table-column prop="username" label="用户" width="120"/><el-table-column prop="action" label="操作" width="180"/><el-table-column prop="target" label="目标" width="170"/><el-table-column prop="detail" label="详情" min-width="200" show-overflow-tooltip/><el-table-column prop="ip" label="来源 IP" width="130"/></el-table><div class="pagination-wrap"><span>共 {{auditTotal}} 条</span><el-pagination v-model:current-page="auditPage" :page-size="20" :total="auditTotal" layout="prev,pager,next" @current-change="loadAudit"/></div></section></div>
  <el-dialog v-model="disableTotpDialog" title="关闭两步验证" width="min(420px,calc(100vw - 28px))"><el-form label-position="top"><el-form-item label="当前密码"><el-input v-model="disableForm.password" type="password" show-password /></el-form-item><el-form-item label="动态验证码"><el-input v-model="disableForm.code" maxlength="6" inputmode="numeric" /></el-form-item></el-form><template #footer><el-button @click="disableTotpDialog=false">取消</el-button><el-button type="danger" :loading="totpLoading" @click="disableTotp">确认关闭</el-button></template></el-dialog>
  <el-dialog v-model="userDialog" title="添加后台用户" width="min(480px,calc(100vw - 28px))"><el-form ref="userRef" :model="newUser" :rules="userRules" label-position="top"><el-form-item label="用户名" prop="username"><el-input v-model="newUser.username" autocomplete="off"/></el-form-item><el-form-item label="初始密码" prop="password"><el-input v-model="newUser.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="显示名称"><el-input v-model="newUser.display_name"/></el-form-item><el-form-item label="邮箱"><el-input v-model="newUser.email"/></el-form-item><el-form-item label="角色" prop="role_id"><el-select v-model="newUser.role_id" style="width:100%"><el-option v-for="r in roles" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="userDialog=false">取消</el-button><el-button type="primary" :loading="userSaving" @click="createUser">创建</el-button></template></el-dialog>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import QRCode from 'qrcode'
import { Plus, Refresh } from '@element-plus/icons-vue'
import { api } from '../api'
import UpdatePanel from '../components/UpdatePanel.vue'
const passwordRef=ref(),passwordLoading=ref(false),password=reactive({old_password:'',new_password:'',confirm:''}),passwordRules={old_password:[{required:true,message:'请输入当前密码',trigger:'blur'}],new_password:[{required:true,min:8,message:'新密码至少 8 位',trigger:'blur'}],confirm:[{validator:(_:any,v:string,cb:any)=>v===password.new_password?cb():cb(new Error('两次密码不一致')),trigger:'blur'}]}
const retentionDays=ref(30),savingRetention=ref(false)
const alertWebhookUrl=ref(''),alertChannelType=ref('auto'),savingAlert=ref(false),testingAlert=ref(false)
const users=ref<any[]>([]),roles=ref<any[]>([]),audits=ref<any[]>([]),userLoading=ref(false),auditLoading=ref(false),userSaving=ref(false),userDialog=ref(false),userRef=ref(),auditPage=ref(1),auditTotal=ref(0),newUser=reactive<any>({username:'',password:'',display_name:'',email:'',role_id:null})
const totpEnabled=ref(false),totpSetup=ref<any>(null),totpQr=ref(''),totpCode=ref(''),totpLoading=ref(false),disableTotpDialog=ref(false),disableForm=reactive({password:'',code:''})
const sessions=ref<any[]>([]),sessionsLoading=ref(false)
const userRules={username:[{required:true,min:3,message:'用户名至少 3 位',trigger:'blur'}],password:[{required:true,min:8,message:'密码至少 8 位',trigger:'blur'}],role_id:[{required:true,message:'请选择角色',trigger:'change'}]}
async function loadRetention(){try{const {data}=await api.get('/system/settings');const found=data.find((x:any)=>x.key==='data_retention_days');if(found&&found.value!==undefined)retentionDays.value=Number(found.value);const urlFound=data.find((x:any)=>x.key==='alert_webhook_url');if(urlFound&&urlFound.value!==undefined)alertWebhookUrl.value=String(urlFound.value);const typeFound=data.find((x:any)=>x.key==='alert_channel_type');if(typeFound&&typeFound.value!==undefined)alertChannelType.value=String(typeFound.value)}catch{}}
async function saveRetention(){savingRetention.value=true;try{await api.put('/system/settings/data_retention_days',{value:retentionDays.value});ElMessage.success('数据生命周期保留配置已更新')}catch(err:any){ElMessage.error(err.response?.data?.detail||'保存失败')}finally{savingRetention.value=false}}
async function saveAlertConfig(){savingAlert.value=true;try{await Promise.all([api.put('/system/settings/alert_webhook_url',{value:alertWebhookUrl.value.trim()}),api.put('/system/settings/alert_channel_type',{value:alertChannelType.value})]);ElMessage.success('告警通道配置已保存')}catch(err:any){ElMessage.error(err.response?.data?.detail||'保存告警配置失败')}finally{savingAlert.value=false}}
async function testAlertWebhook(){if(!alertWebhookUrl.value.trim()){ElMessage.warning('请先填写 Webhook URL');return}testingAlert.value=true;try{const {data}=await api.post('/system/alert/test',{webhook_url:alertWebhookUrl.value.trim(),channel_type:alertChannelType.value});if(data.ok)ElMessage.success('测试告警推送成功，请在对应应用中查收！');else ElMessage.error(data.message||'推送失败')}catch(err:any){ElMessage.error(err.response?.data?.detail||'测试推送失败')}finally{testingAlert.value=false}}
async function changePassword(){await passwordRef.value?.validate(async(valid:boolean)=>{if(!valid)return;passwordLoading.value=true;try{const {data}=await api.post('/auth/password',{old_password:password.old_password,new_password:password.new_password});ElMessage.success(data.detail||'密码已修改');Object.assign(password,{old_password:'',new_password:'',confirm:''})}finally{passwordLoading.value=false}})}
async function loadUsers(){userLoading.value=true;try{const [u,r]=await Promise.all([api.get('/users',{params:{page:1,page_size:100}}),api.get('/roles')]);users.value=u.data.items||[];roles.value=r.data}catch{ }finally{userLoading.value=false}}
async function loadTotp(){try{const {data}=await api.get('/auth/2fa');totpEnabled.value=!!data.enabled}catch{}}
async function setupTotp(){totpLoading.value=true;try{const {data}=await api.post('/auth/2fa/setup');totpSetup.value=data;totpQr.value=await QRCode.toDataURL(data.provisioning_uri,{width:190,margin:1})}finally{totpLoading.value=false}}
function cancelTotpSetup(){totpSetup.value=null;totpQr.value='';totpCode.value=''}
async function confirmTotp(){if(!/^\d{6}$/.test(totpCode.value)){ElMessage.warning('请输入 6 位验证码');return}totpLoading.value=true;try{await api.post('/auth/2fa/confirm',{code:totpCode.value});ElMessage.success('两步验证已启用');totpEnabled.value=true;cancelTotpSetup();await loadSessions()}finally{totpLoading.value=false}}
async function disableTotp(){if(!disableForm.password||!/^[0-9]{6}$/.test(disableForm.code)){ElMessage.warning('请输入密码和 6 位验证码');return}totpLoading.value=true;try{await api.post('/auth/2fa/disable',disableForm);ElMessage.success('两步验证已关闭，请重新登录');localStorage.removeItem('qbot_token');location.href='/login'}finally{totpLoading.value=false}}
async function loadSessions(){sessionsLoading.value=true;try{const {data}=await api.get('/auth/sessions');sessions.value=data||[]}finally{sessionsLoading.value=false}}
async function revokeSession(row:any){try{await ElMessageBox.confirm(`确定撤销来自 ${row.ip||'未知 IP'} 的会话吗？`,'撤销会话',{type:'warning'});await api.delete(`/auth/sessions/${row.id}`);ElMessage.success('会话已撤销');await loadSessions()}catch{}}
async function revokeOtherSessions(){try{await ElMessageBox.confirm('其它设备将立即退出登录，是否继续？','撤销其它会话',{type:'warning'});await api.post('/auth/sessions/revoke-others');ElMessage.success('其它会话已撤销');await loadSessions()}catch{}}
function copyText(value:string){navigator.clipboard?.writeText(value);ElMessage.success('密钥已复制')}
async function loadAudit(){auditLoading.value=true;try{const {data}=await api.get('/audit-logs',{params:{page:auditPage.value,page_size:20}});audits.value=data.items||[];auditTotal.value=data.total||0}finally{auditLoading.value=false}}
async function createUser(){await userRef.value?.validate(async(valid:boolean)=>{if(!valid)return;userSaving.value=true;try{const {data}=await api.post('/users',newUser);ElMessage.success(`用户 ${data.username} 已创建`);userDialog.value=false;Object.assign(newUser,{username:'',password:'',display_name:'',email:'',role_id:null});await loadUsers()}finally{userSaving.value=false}})}
async function toggleUser(u:any){try{const {data}=await api.put(`/users/${u.id}`,{is_active:!u.is_active});ElMessage.success(data.username+' 已更新');await loadUsers()}catch{}}
function formatDate(v:string){return v?new Date(v).toLocaleString('zh-CN'):'—'}
onMounted(()=>{loadUsers();loadAudit();loadRetention();loadTotp();loadSessions()})
</script>
<style scoped>.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.settings-panel{padding:18px}.settings-panel .el-form{max-width:500px}.security-note{margin-top:18px}.security-action{display:flex;align-items:center;justify-content:space-between;gap:16px;color:#aab6c9;font-size:11px;line-height:1.6}.totp-setup{display:grid;grid-template-columns:210px 1fr;gap:22px;align-items:start}.totp-qr{display:grid;place-items:center;min-height:210px;padding:10px;background:#101722;border:1px solid #29364c;border-radius:10px}.totp-qr img{width:190px;height:190px}.totp-copy{min-width:0}.update-panel{grid-column:1/-1}.update-summary{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.update-summary>div{min-width:130px;padding:10px 12px;border:1px solid #29364c;border-radius:8px;background:#111927}.update-summary span,.update-summary b{display:block}.update-summary span{color:#7d8ba1;font-size:10px}.update-summary b{margin-top:4px;color:#dce7f7;font-size:15px}.update-actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.release-notes{margin-top:16px}.release-notes pre{max-height:240px;overflow:auto;padding:12px;border:1px solid #29364c;border-radius:8px;background:#0d141f;color:#aebbd0;font:11px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap}.asset-table{margin-top:16px}.sessions-panel{grid-column:1/-1;min-width:0;overflow:auto}.session-footer{display:flex;align-items:center;justify-content:space-between;padding-top:12px;color:#8290a5;font-size:10px}.subtext{margin-top:5px;color:#7d8ba1;font-size:10px}.users-panel{min-width:0;overflow:auto}.audit-panel{grid-column:1/-1;min-width:0;overflow:auto}.pagination-wrap{display:flex;justify-content:space-between;align-items:center;padding-top:12px;color:#8390a4;font-size:10px}@media(max-width:950px){.settings-grid{grid-template-columns:1fr}.audit-panel{grid-column:auto}.update-panel{grid-column:auto}}@media(max-width:650px){.totp-setup{grid-template-columns:1fr}.security-action,.session-footer{align-items:flex-start;flex-direction:column}}</style>
